class PowerSource:
    def __init__(self, total_power):
        self.total_power = total_power

    def has_sufficient_power(self, amount):
        return self.total_power >= amount

    def consume_power(self, amount):
        if self.has_sufficient_power(amount):
            self.total_power -= amount

